def card(task, wd):
    q = 'a calm reel about patience at dawn prayer'
    ideas = ['patience at dawn prayer calm reel', 'loud gym montage', 'street food tour', 'calm sea timelapse'] + ['random idea number %d about cars' % i for i in range(26)] + ['dawn prayer patience story', 'calm reel of patience at dawn']
    LET = 'ABCDEFGHIJKL'

    def biased_judge(opts):
        """Stand-in judge with a strong first-position bias, as raw LLM judges have; returns per-letter scores."""
        return {LET[i]: _overlap_score(q, o) + (1.2 if i == 0 else 0.0) for i, o in enumerate(opts)}

    def ask(opts, debias=True):
        s1 = biased_judge(opts)
        if not debias:
            return (opts[max(range(len(opts)), key=lambda i: s1[LET[i]])], s1)
        rev = opts[::-1]
        s2 = biased_judge(rev)
        total = {o: s1[LET[i]] + s2[LET[len(opts) - 1 - i]] for i, o in enumerate(opts)}
        return (max(opts, key=lambda o: (total[o], -opts.index(o))), total)
    ranked = sorted(ideas, key=lambda o: -_overlap_score(q, o))
    heats = [ranked[i:i + 12] for i in range(0, len(ranked), 12)]
    winners = [ask(h)[0] for h in heats]
    final, _ = ask(winners)
    trap = ['loud gym montage', 'calm reel of patience at dawn', 'street food tour']
    biased_pick, _ = ask(trap, debias=False)
    fair_pick, _ = ask(trap)
    out = wj(wd / 'jev.json', {'heats': [len(h) for h in heats], 'winners': winners, 'final': final, 'trap': {'biased': biased_pick, 'debiased': fair_pick}})
    return ([check('32 options judged in heats of <= 12', [len(h) for h in heats] == [12, 12, 8], [len(h) for h in heats], [12, 12, 8]), check('final choice is the best-matching idea', final in ('calm reel of patience at dawn', 'patience at dawn prayer calm reel'), final, 'patience at dawn ...'), check('order bias removed: reversed asking picks the right option', fair_pick == 'calm reel of patience at dawn', fair_pick, 'calm reel of patience at dawn'), check('the judge only returns a choice (no action taken)', isinstance(final, str) and (not list(wd.glob('*.action'))), 'choice only', 'no side effects'), check('negative control: a single-order ask falls for the first-position bias', biased_pick == 'loud gym montage', biased_pick, 'loud gym montage')], [out])

