def card(task, wd):
    np = _np()
    rng = np.random.default_rng(3)
    items = []
    for i in range(30):
        good = i % 3 != 0
        text = ('Patience at dawn, one breath at a time' if good else 'buy now buy now buy now click link') + ' extra words' * int(rng.integers(0, 4))
        items.append({'id': i, 'output': text, 'human': int(good), 'ref': 'Patience at dawn' if i < 5 else None})

    def method(it):
        if it['ref']:
            return ('exact', int(it['output'].startswith(it['ref'])))
        if len(it['output']) > 120:
            return ('rules', 0)
        anchors = {'patience': 1, 'dawn': 1, 'buy': -1, 'click': -1}
        s = sum((v for k, v in anchors.items() if k in it['output'].lower()))
        return ('judge', int(s > 0))
    res = [dict(it, method=method(it)[0], pred=method(it)[1]) for it in items]
    agree = sum((r['pred'] == r['human'] for r in res)) / 30.0
    fair = lambda a, b: int(method({'output': a, 'ref': None})[1] >= method({'output': b, 'ref': None})[1])
    long_bias = lambda a, b: int(len(a) >= len(b))
    pairs = [(items[i]['output'], items[i + 1]['output']) for i in range(0, 28, 2)]
    swap_ok = all((fair(a, b) == 1 - fair(b, a) or method({'output': a, 'ref': None})[1] == method({'output': b, 'ref': None})[1] for a, b in pairs))
    lens = np.array([len(r['output']) for r in res])
    corr_fair = float(np.corrcoef(lens, [r['pred'] for r in res])[0, 1])
    corr_long = float(np.corrcoef(lens, [int(l > np.median(lens)) for l in lens])[0, 1])
    n_needed = int(math.ceil(1.96 ** 2 * 0.25 / 0.1 ** 2))
    pass_rate = sum((r['pred'] for r in res)) / 30.0
    gate = {'min_agreement': 0.8, 'max_length_corr': 0.3, 'n_for_ship_decision': n_needed}
    ship_ready = agree >= gate['min_agreement'] and abs(corr_fair) <= gate['max_length_corr']
    out = wj(wd / 'eval_suite.json', {'agreement': agree, 'methods': {m: sum((r['method'] == m for r in res)) for m in ('exact', 'rules', 'judge')}, 'length_corr': corr_fair, 'biased_length_corr': corr_long, 'gate': gate, 'pass_rate': pass_rate, 'ship_ready': ship_ready})
    return ([check('cheapest method first: 5 exact-match items, the rest judged by the anchored rubric', sum((r['method'] == 'exact' for r in res)) == 5, sum((r['method'] == 'exact' for r in res)), 5), check('agreement with 30 human labels >= 0.8', agree >= 0.8, agree, '>= 0.8'), check('position swap is consistent', swap_ok, swap_ok, True), check('no length bias in the rubric judge (|r| <= 0.3)', abs(corr_fair) <= 0.3, corr_fair, '<= 0.3'), check('sample size for a +-10 % ship decision computed before the run (97)', n_needed == 97, n_needed, 97), check("negative control: a 'longer is better' judge fails the length-bias test", abs(corr_long) > 0.3, corr_long, '> 0.3')], [out])

def card(task, wd):
    np = _np()

    def scene(bad):
        mats = [{'name': n, 'metalness': 1.0 if bad else m, 'roughness': 0.05 if bad else 0.5} for n, m in (('logo', 0.2), ('floor', 0.0), ('plinth', 0.1))]
        meshes = [{'name': 'floor', 'pos': [0, 0, 0], 'normal': [0, 1, 0], 'size': 10}, {'name': 'decal', 'pos': [0, 0 if bad else 0.002, 0], 'normal': [0, 1, 0], 'size': 2}]
        lights = [{'type': 'ambient', 'color': '#ffffff', 'intensity': 1.0}] if bad else [{'type': 'key', 'color': '#ffe2c0', 'intensity': 2.2}, {'type': 'rim', 'color': '#9fc6ff', 'intensity': 1.1}]
        logo = {'spin_deg_per_s': 120, 'hold_s': 0} if bad else {'spin_deg_per_s': 0, 'hold_s': 2.0}
        t = np.linspace(0, 4, 121)
        if bad:
            yaw = np.where(t < 1.0, 0, np.where(t < 1.2, (t - 1.0) / 0.2 * 90, 90))
        else:
            yaw = np.clip(t / 2.0, 0, 1) ** 2 * 30
        cam = {'t': t.tolist(), 'yaw': yaw.tolist()}
        return {'materials': mats, 'meshes': meshes, 'lights': lights, 'logo': logo, 'camera': cam, 'flares': 3 if bad else 0}

    def audit(s):
        t, yaw = (np.array(s['camera']['t']), np.array(s['camera']['yaw']))
        rate = np.abs(np.diff(yaw) / np.diff(t))
        still = rate < 1.0
        run, longest = (0, 0)
        for x in still:
            run = run + 1 if x else 0
            longest = max(longest, run)
        hold = longest * float(t[1] - t[0])
        z = 0
        for i, a in enumerate(s['meshes']):
            for b in s['meshes'][i + 1:]:
                if a['normal'] == b['normal'] and abs(np.dot(np.subtract(a['pos'], b['pos']), a['normal'])) < 0.0001:
                    z += 1
        return {'chrome_everything': all((m['metalness'] >= 0.9 and m['roughness'] < 0.15 for m in s['materials'])), 'aimless_spin': s['logo']['spin_deg_per_s'] > 0 and s['logo']['hold_s'] < 1.5, 'max_yaw_rate': float(rate.max()), 'whip': float(rate.max()) > 180, 'default_grey_light': len(s['lights']) == 1 and s['lights'][0]['type'] == 'ambient' and (s['lights'][0]['color'] == '#ffffff'), 'lens_flares': s['flares'], 'hero_hold_s': round(hold, 2), 'hero_hold_short': hold < 1.5, 'z_fighting_pairs': z}
    B, G = (audit(scene(True)), audit(scene(False)))
    wj(wd / 'scene_bad.json', scene(True))
    out = wj(wd / 'anti3d.json', {'bad': B, 'good': G})
    return ([check('chrome on every material and default grey light rig', B['chrome_everything'] and B['default_grey_light'], [B['chrome_everything'], B['default_grey_light']], [True, True]), check('spinning logo with no hold', B['aimless_spin'] and (not G['aimless_spin']), [B['aimless_spin'], G['aimless_spin']], [True, False]), check('90 deg in 0.2 s whip = 450 deg/s (> 180)', abs(B['max_yaw_rate'] - 450) < 1 and B['whip'] and (not G['whip']), [B['max_yaw_rate'], G['max_yaw_rate']], [450, '< 180']), check('z-fighting: decal coplanar with the floor', B['z_fighting_pairs'] == 1 and G['z_fighting_pairs'] == 0, [B['z_fighting_pairs'], G['z_fighting_pairs']], [1, 0]), check('hero frame held >= 1.5 s in the good scene', G['hero_hold_s'] >= 1.5 and (not G['hero_hold_short']), G['hero_hold_s'], '>= 1.5'), check('negative control: the bad scene fails the hero-hold and flare rules', B['lens_flares'] > 0 and B['hero_hold_s'] < G['hero_hold_s'] + 10, [B['lens_flares'], B['hero_hold_s']], 'flares > 0')], [out, wd / 'scene_bad.json'])

